Here is the commit message:
ALSA: usb-audio: stop parsing UAC2 rates at MAX_NR_RATES
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

parse_uac2_sample_rate_range() caps the number of enumerated
rates at MAX_NR_RATES, but it only breaks out of the current
rate loop. A malformed UAC2 RANGE response with additional
triplets continues parsing the remaining triplets and repeatedly
prints "invalid uac2 rates" while probe still holds
register_mutex.

Stop the whole parse once the cap is reached and return the
number of rates collected so far.

Fixes: 4fa0e81b8350 ("ALSA: usb-audio: fix possible hang and overflow in parse_uac2_sample_rate_range()")
Cc: stable@vger.kernel.org
Reported-by: syzbot+d56178c27a4710960820@syzkaller.appspotmail.com
Closes: https://syzkaller.appspot.com/bug?extid=d56178c27a4710960820
Signed-off-by: Cássio Gabriel <cassiogabrielcontato@gmail.com>
Link: https://patch.msgid.link/20260415-usb-audio-uac2-rate-cap-v1-1-5ecbafc120d8@gmail.com
Signed-off-by: Takashi Iwai <tiwai@suse.de>

Here is the root cause:
In the function parse_uac2_sample_rate_range(), when the number of enumerated sample rates reaches MAX_NR_RATES, the original code used a 'break' statement which only exits the inner loop over rates within a single triplet. However, the outer loop over multiple triplets continues, causing repeated parsing of additional triplets in a malformed UAC2 RANGE response. This results in repeated "invalid uac2 rates" error messages and potential hang because the probe function holds the register_mutex, preventing other operations.

Here is the patch:
  */
 static int parse_uac2_sample_rate_range(struct snd_usb_audio *chip,
 					struct audioformat *fp, int nr_triplets,
 					const unsigned char *data)
 {
 	int i, nr_rates = 0;

 	for (i = 0; i < nr_triplets; i++) {
 		int min = combine_quad(&data[2 + 12 * i]);
 		int max = combine_quad(&data[6 + 12 * i]);
 		int res = combine_quad(&data[10 + 12 * i]);
 		unsigned int rate;

 		if ((max < 0) || (min < 0) || (res < 0) || (max < min))
 			continue;

 		/*
 		 * for ranges with res == 1, we announce a continuous sample
 		 * rate range, and this function should return 0 for no further
 		 * parsing.
 		 */
 		if (res == 1) {
 			fp->rate_min = min;
 			fp->rate_max = max;
 			fp->rates = SNDRV_PCM_RATE_CONTINUOUS;
 			return 0;
 		}

 		for (rate = min; rate <= max; rate += res) {

 			/* Filter out invalid rates on Presonus Studio 1810c */
 			if (chip->usb_id == USB_ID(0x194f, 0x010c) &&
 			    !s1810c_valid_sample_rate(fp, rate))
 				goto skip_rate;
 			/* Filter out invalid rates on Presonus Studio 1824c */
 			if (chip->usb_id == USB_ID(0x194f, 0x010d) &&
 			    !s1810c_valid_sample_rate(fp, rate))
 				goto skip_rate;
 			/* Filter out invalid rates on Presonus Studio 1824 */
 			if (chip->usb_id == USB_ID(0x194f, 0x0107) &&
 			    !s1810c_valid_sample_rate(fp, rate))
 				goto skip_rate;

 			/* Filter out invalid rates on Focusrite devices */
 			if (USB_ID_VENDOR(chip->usb_id) == 0x1235 &&
 			    !focusrite_valid_sample_rate(chip, fp, rate))
 				goto skip_rate;

 			if (fp->rate_table)
 				fp->rate_table[nr_rates] = rate;
 			nr_rates++;
 			if (nr_rates >= MAX_NR_RATES) {
 				usb_audio_err(chip, "invalid uac2 rates\n");
-				break;
+				return nr_rates;
 			}

 skip_rate:
 			/* avoid endless loop */
 			if (res == 0)
 				break;
 		}
 	}

 	return nr_rates;
 }



